    # Branch Audit (check all 4 natal branches)
    _unified_medicine = set(medicine)
    _unified_taboo = set(taboo)
    _shen_profile = profile.shen_profile
    if _shen_profile is not None:
        _unified_medicine |= set(getattr(_shen_profile, "yong_shen", []) or []) | set(getattr(_shen_profile, "xi_shen", []) or [])
        _unified_taboo |= set(getattr(_shen_profile, "ji_shen", []) or []) | set(getattr(_shen_profile, "chou_shen", []) or [])

    def _check_polarity(el) -> int:
        if el is None:
            return 0
        med_strs = {str(x) for x in _unified_medicine}
        tab_strs = {str(x) for x in _unified_taboo}
        el_str = str(el)
        if el_str in med_strs:
            return 1
        elif el_str in tab_strs:
            return -1
        return 0

    ty_branch_impact = 0
    _all = frozenset([ty_branch, *natal_branches])

    for nb in natal_branches:
        # Check priority order: 三会 > 三合 > 冲 > 六合 > 半合 > 刑 > 害 > 破

        # 1. 三会 (San Hui)
        found = False
        for element, branches in SAN_HUI.items():
            if {ty_branch, nb} <= branches and branches <= _all:
                ty_branch_impact += 20 * 1 * _check_polarity(element)
                found = True
                break
        if found:
            continue

        # 2. 三合 (San He)
        for element, branches in SAN_HE.items():
            if {ty_branch, nb} <= branches and branches <= _all:
                ty_branch_impact += 18 * 1 * _check_polarity(element)
                found = True
                break
        if found:
            continue

        # 3. 冲 (Chong)
        _c = CHONG.get(ty_branch)
        is_chong = False
        if _c is not None:
            if (isinstance(_c, str) and _c == nb) or (getattr(_c, "label", None) == nb) or (str(_c) == nb):
                is_chong = True
        if is_chong:
            target_el = (eb := BRANCHES.get(nb)) and eb.element
            ty_branch_impact += 30 * -1 * _check_polarity(target_el)
            continue

        # 4. 六合 (Liu He)
        if frozenset({ty_branch, nb}) in LIU_HE:
            element = None
            if isinstance(LIU_HE, dict):
                element = LIU_HE.get(frozenset({ty_branch, nb}))
            ty_branch_impact += 15 * 1 * _check_polarity(element)
            continue

        # 5. 半合 (Ban He)
        if frozenset({ty_branch, nb}) in BAN_HE_RESULTS:
            element = BAN_HE_RESULTS.get(frozenset({ty_branch, nb}))
            ty_branch_impact += 10 * 1 * _check_polarity(element)
            continue

        # 6. 刑 (Xing)
        is_xing = False
        for group in XING.values():
            if ty_branch in group and nb in group:
                is_xing = True
                break
        if is_xing:
            target_el = (eb := BRANCHES.get(nb)) and eb.element
            ty_branch_impact += 15 * -1 * _check_polarity(target_el)
            continue

        # 7. 害 (Hai)
        _h = HAI.get(ty_branch)
        is_hai = False
        if _h is not None:
            if (isinstance(_h, str) and _h == nb) or (getattr(_h, "label", None) == nb) or (str(_h) == nb):
                is_hai = True
        if is_hai:
            target_el = (eb := BRANCHES.get(nb)) and eb.element
            ty_branch_impact += 15 * -1 * _check_polarity(target_el)
            continue

        # 8. 破 (Po)
        _p = PO.get(ty_branch)
        is_po = False
        if _p is not None:
            if (isinstance(_p, str) and _p == nb) or (getattr(_p, "label", None) == nb) or (str(_p) == nb):
                is_po = True
        if is_po:
            target_el = (eb := BRANCHES.get(nb)) and eb.element
            ty_branch_impact += 15 * -1 * _check_polarity(target_el)
            continue
